use std::rc::Rc;use std::cell::RefCell;impl Solution{pub fn largest_bst_subtree(root:Option<Rc<RefCell<TreeNode>>>)->i32{fn f(n:&Option<Rc<RefCell<TreeNode>>>,b:&mut i32)->(bool,i32,i32,i32){if let Some(x)=n{let q=x.borrow();let l=f(&q.left,b);let r=f(&q.right,b);if l.0&&r.0&&q.val>l.3&&q.val<r.2{let sz=l.1+r.1+1;*b=(*b).max(sz);return(true,sz,if l.1>0{l.2}else{q.val},if r.1>0{r.3}else{q.val})}(false,0,0,0)}else{(true,0,i32::MAX,i32::MIN)}}let mut b=0;f(&root,&mut b);b}}
